import java.util.*;

class Solution {
    public List<List<String>> groupFamilies(String[] words) {
        HashMap<String, List<String>> map = new HashMap<>();
        for (String w : words) {
            char[] c = w.toCharArray();
            Arrays.sort(c);
            String key = new String(c); // same letters -> same key
            if (!map.containsKey(key)) map.put(key, new ArrayList<String>());
            map.get(key).add(w);
        }
        List<List<String>> groups = new ArrayList<>();
        for (List<String> g : map.values()) {
            Collections.sort(g); // words inside a group alphabetically
            groups.add(g);
        }
        // A word belongs to only one group, so comparing first words orders the groups
        Collections.sort(groups, new Comparator<List<String>>() {
            public int compare(List<String> x, List<String> y) {
                return x.get(0).compareTo(y.get(0));
            }
        });
        return groups;
    }
}

