function groupFamilies(words) {
  const m = new Map();
  for (const w of words) { const k = w.split("").sort().join(""); if (!m.has(k)) m.set(k, []); m.get(k).push(w); }
  const cmp = (x, y) => (x < y ? -1 : x > y ? 1 : 0);
  const gs = [...m.values()].map((g) => g.sort(cmp));
  gs.sort((p, q) => { for (let i = 0; i < Math.min(p.length, q.length); i++) { const c = cmp(p[i], q[i]); if (c) return c; } return p.length - q.length; });
  return gs;
}
